  ('fg-g00152', 'forest-governance', 'social-forestry-extension', 'Easy', 'practice',
   'What is a typical component of a social forestry program?',
   '[{"id":"a","text":"Exclusive government control."},{"id":"b","text":"Large-scale commercial logging operations."},{"id":"c","text":"Community involvement and benefit-sharing."},{"id":"d","text":"Reforestation with non-native species only."}]'::jsonb, 'c'),
  ('fg-g00153', 'forest-governance', 'social-forestry-extension', 'Easy', 'practice',
   'Which organization is primarily responsible for implementing social forestry projects in the Philippines?',
