   'What is the key component of extension services in social forestry that involves educating community members about sustainable forest management practices?',
   '[{"id":"a","text":"Financial incentives program"},{"id":"b","text":"Infrastructure development"},{"id":"c","text":"Resource extraction permits"},{"id":"d","text":"Technical training workshops"}]'::jsonb, 'd'),
  ('fg-g00176', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'In social forestry, which practice involves integrating trees into agricultural lands to improve biodiversity and soil fertility?',
   '[{"id":"a","text":"Agroforestry"},{"id":"b","text":"Silviculture"},{"id":"c","text":"Monoculture plantations"},{"id":"d","text":"Wildlife reserves"}]'::jsonb, 'a'),
  ('fg-g00177', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'What is a primary goal of capacity building activities in social forestry programs?',
