  ('fg-g00180', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'Which community right is crucial in social forestry and allows local groups to manage forest lands according to traditional practices?',
   '[{"id":"a","text":"Right to exclusive commercial logging"},{"id":"b","text":"Right to private ownership"},{"id":"c","text":"Right to ancestral domain"},{"id":"d","text":"Right to mineral extraction"}]'::jsonb, 'c'),
  ('fg-g00181', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'In the context of social forestry, what is the importance of establishing buffer zones?',
   '[{"id":"a","text":"To increase logging activities"},{"id":"b","text":"To provide areas for intensive agriculture"},{"id":"c","text":"To minimize human impact on core conservation areas"},{"id":"d","text":"To develop urban infrastructure"}]'::jsonb, 'c'),
  ('fg-g00182', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'What is the role of tenure instruments like Certificate of Stewardship Contract (CSC) in social forestry?',
   '[{"id":"a","text":"To provide legal grounds for land conversion"},{"id":"b","text":"To enforce strict logging quotas"},{"id":"c","text":"To grant temporary land access for sustainable management"},{"id":"d","text":"To allow commercial mining operations"}]'::jsonb, 'c'),
  ('fg-g00183', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'Which of the following best describes a participatory approach in social forestry?',
   '[{"id":"a","text":"Top-down policy enforcement by government agencies"},{"id":"b","text":"Joint decision-making involving local communities and authorities"},{"id":"c","text":"Exclusive management by private corporations"},{"id":"d","text":"Complete deregulation of forest resources"}]'::jsonb, 'b'),
  ('fg-g00184', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'What is a key benefit of social forestry programs for local communities?',
   '[{"id":"a","text":"Increased access to commercial logging opportunities."},{"id":"b","text":"Improved soil fertility through the integration of leguminous trees."},{"id":"c","text":"Higher rates of deforestation in protected areas."},{"id":"d","text":"Guaranteed employment in national timber corporations."}]'::jsonb, 'b'),
  ('fg-g00185', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'Which strategy is often used in social forestry to enhance community engagement?',
   '[{"id":"a","text":"Top-down management by government agencies."},{"id":"b","text":"Participatory planning and decision-making."},{"id":"c","text":"Establishment of private plantations."},{"id":"d","text":"Exclusive focus on commercial timber production."}]'::jsonb, 'b'),
  ('fg-g00186', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'In social forestry, what is the role of extension services related to community development?',
