  ('fg-g00187', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'Which approach is commonly used in social forestry to ensure sustainable management of forest resources?',
   '[{"id":"a","text":"Focus on monoculture plantations."},{"id":"b","text":"Sole reliance on government enforcement."},{"id":"c","text":"Outsourcing management to international corporations."},{"id":"d","text":"Community-based resource management."}]'::jsonb, 'd'),
  ('fg-g00188', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'How does agroforestry contribute to the objectives of social forestry?',
   '[{"id":"a","text":"By reducing tree cover to expand agricultural lands."},{"id":"b","text":"By converting natural forests into urban spaces."},{"id":"c","text":"By focusing exclusively on non-native tree species."},{"id":"d","text":"By promoting biodiversity and improving food security."}]'::jsonb, 'd'),
  ('fg-g00189', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'What is the primary function of a Certificate of Ancestral Domain Title (CADT) in social forestry?',
   '[{"id":"a","text":"To privatize forest lands for commercial use."},{"id":"b","text":"To transfer forest land ownership to multinational companies."},{"id":"c","text":"To recognize the ancestral rights of indigenous communities over their lands."},{"id":"d","text":"To restrict access to forest resources for local communities."}]'::jsonb, 'c'),
  ('fg-g00190', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'Which of the following is a common goal of community-based forest management in social forestry?',
   '[{"id":"a","text":"To maximize timber extraction without community consent."},{"id":"b","text":"To focus solely on single-species plantations for export."},{"id":"c","text":"To eliminate all forms of traditional forest use."},{"id":"d","text":"To involve local communities in decision-making processes."}]'::jsonb, 'd'),
  ('fg-g00191', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'In the context of social forestry, what is a typical role of non-governmental organizations (NGOs)?',
   '[{"id":"a","text":"To support community capacity building and advocacy."},{"id":"b","text":"To monopolize access to forest resources."},{"id":"c","text":"To restrict community access to external funding."},{"id":"d","text":"To manage forests independently of local communities."}]'::jsonb, 'a'),
  ('fg-g00192', 'forest-governance', 'social-forestry-extension', 'Medium', 'practice',
   'What is a primary consideration in the design of social forestry projects?',
   '[{"id":"a","text":"Maximizing short-term economic returns."},{"id":"b","text":"Exclusive use of exotic species."},{"id":"c","text":"Complete governmental control with no community input."},{"id":"d","text":"Ensuring ecological sustainability and community benefits."}]'::jsonb, 'd'),
