  ('fg-g00416', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'In the context of professional ethics, how should foresters manage conflicts of interest?',
   '[{"id":"a","text":"Ignore the conflict as long as it is not apparent to others."},{"id":"b","text":"Disclose the conflict to all parties involved and seek resolution."},{"id":"c","text":"Delegate the responsibility to a colleague."},{"id":"d","text":"Prioritize personal gain over professional duties."}]'::jsonb, 'b'),
  ('fg-g00417', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'According to professional ethics, how should foresters handle confidential information about forest management plans?',
   '[{"id":"a","text":"Share with all stakeholders without restrictions."},{"id":"b","text":"Post online for public access."},{"id":"c","text":"Only disclose to parties with a legitimate interest or requirement for the information."},{"id":"d","text":"Sell the information to the highest bidder."}]'::jsonb, 'c'),
  ('fg-g00418', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'What is the ethical approach for a forester when receiving gifts from clients?',
   '[{"id":"a","text":"Accept gifts regardless of value to maintain good client relations."},{"id":"b","text":"Reject all gifts to avoid any ethical concerns."},{"id":"c","text":"Accept only if the gift does not influence professional judgment or decisions."},{"id":"d","text":"Only accept gifts that have significant monetary value."}]'::jsonb, 'c'),
  ('fg-g00419', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'How should foresters ethically respond to witnessing environmental violations in their area of responsibility?',
   '[{"id":"a","text":"Ignore the violations to maintain good relations with local communities."},{"id":"b","text":"Document and report the violations to the appropriate authorities."},{"id":"c","text":"Take personal action to punish the violators."},{"id":"d","text":"Wait for someone else to report the issue."}]'::jsonb, 'b'),
  ('fg-g00420', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'Which ethical consideration should guide a forester''s decision-making when developing a forest management plan?',
   '[{"id":"a","text":"Ensuring sustainable use of forest resources while balancing economic, social, and environmental factors."},{"id":"b","text":"Maximizing financial profit regardless of environmental impact."},{"id":"c","text":"Focusing solely on environmental preservation without regard to social impacts."},{"id":"d","text":"Ignoring scientific data in favor of traditional beliefs."}]'::jsonb, 'a'),
  ('fg-g00421', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'What should a forester do according to professional ethics when their personal beliefs conflict with professional responsibilities?',
   '[{"id":"a","text":"Prioritize personal beliefs over professional duties."},{"id":"b","text":"Resign from their position."},{"id":"c","text":"Seek guidance to reconcile the conflict while upholding professional standards."},{"id":"d","text":"Ignore professional standards and act according to personal beliefs."}]'::jsonb, 'c'),
  ('fg-g00422', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'In terms of professional ethics, how should foresters deal with professional mistakes?',
   '[{"id":"a","text":"Acknowledge the mistake, take responsibility, and learn from it."},{"id":"b","text":"Conceal the mistake to protect their reputation."},{"id":"c","text":"Blame a colleague for the mistake."},{"id":"d","text":"Dismiss the mistake as insignificant."}]'::jsonb, 'a'),
  ('fg-g00423', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'Which ethical principle should guide a forester in their interactions with indigenous peoples?',
   '[{"id":"a","text":"Consult and collaborate with indigenous communities, respecting their rights and traditions."},{"id":"b","text":"Exclude indigenous knowledge from decision-making."},{"id":"c","text":"Impose decisions without consultation."},{"id":"d","text":"Assume that indigenous knowledge is outdated and irrelevant."}]'::jsonb, 'a'),
  ('fg-g00424', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'What is an ethical way for foresters to promote sustainable forest management practices?',
   '[{"id":"a","text":"Disregard community involvement and focus on enforcement."},{"id":"b","text":"Engage and educate local communities to foster participation and cooperation."},{"id":"c","text":"Implement strict regulations without public input."},{"id":"d","text":"Only consider government interests in management plans."}]'::jsonb, 'b'),
  ('fg-g00425', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'How should a forester approach the use of new technology in forest management according to professional ethics?',
   '[{"id":"a","text":"Critically assess and adopt technology that enhances sustainability and efficiency."},{"id":"b","text":"Implement new technology without evaluating its environmental impact."},{"id":"c","text":"Ignore technological advancements and stick to traditional methods."},{"id":"d","text":"Use technology solely for cost cutting, regardless of its effects."}]'::jsonb, 'a'),
  ('fg-g00426', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'Which principle should guide a forester in maintaining professional relationships with colleagues and other stakeholders?',
   '[{"id":"a","text":"Authoritarian control"},{"id":"b","text":"Secrecy and exclusivity"},{"id":"c","text":"Passive observation"},{"id":"d","text":"Transparency and openness"}]'::jsonb, 'd'),
  ('fg-g00427', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'How should a professional forester handle a situation where their work is subject to public criticism?',
   '[{"id":"a","text":"Evaluate the criticism constructively and make necessary improvements"},{"id":"b","text":"Ignore the criticism and continue as planned"},{"id":"c","text":"Engage in a defensive argument with critics"},{"id":"d","text":"Reject all feedback and maintain original viewpoints"}]'::jsonb, 'a'),
  ('fg-g00428', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'When confronted with potential environmental harm, what is the ethical stance a forester should take according to professional values?',
   '[{"id":"a","text":"Act to prevent harm even if it conflicts with immediate project goals"},{"id":"b","text":"Prioritize economic benefits over environmental concerns"},{"id":"c","text":"Minimize public awareness to avoid controversy"},{"id":"d","text":"Delay decision-making until harm is unavoidable"}]'::jsonb, 'a'),
  ('fg-g00429', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'What ethical consideration should a forester prioritize when dealing with sensitive information from indigenous communities?',
   '[{"id":"a","text":"Profit from the information commercially"},{"id":"b","text":"Share the information widely for awareness"},{"id":"c","text":"Ignore the information as irrelevant"},{"id":"d","text":"Respect and protect the confidentiality of the information"}]'::jsonb, 'd'),
  ('fg-g00430', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'In terms of professional ethics, how should a forester manage intellectual property associated with forest research?',
   '[{"id":"a","text":"Claim sole ownership regardless of contributors"},{"id":"b","text":"Ensure that all contributors are acknowledged and credited"},{"id":"c","text":"Prevent public access to the research findings"},{"id":"d","text":"Sell the research to the highest bidder"}]'::jsonb, 'b'),
  ('fg-g00431', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'What is the ethical approach for a forester when choosing suppliers for forestry operations?',
   '[{"id":"a","text":"Select suppliers based on personal relationships"},{"id":"b","text":"Select suppliers based on ethical practices and environmental standards"},{"id":"c","text":"Choose suppliers that offer the lowest cost irrespective of quality"},{"id":"d","text":"Choose suppliers who offer the fastest delivery times"}]'::jsonb, 'b'),
  ('fg-g00432', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'How should a forester ethically handle an offer of gifts or hospitality from a client?',
   '[{"id":"a","text":"Accept all gifts and hospitality without question"},{"id":"b","text":"Refuse all offers to avoid any appearance of a conflict"},{"id":"c","text":"Consider the value and intent of the gift, and refuse if it compromises professional judgment"},{"id":"d","text":"Accept gifts in private to avoid scrutiny"}]'::jsonb, 'c'),
  ('fg-g00433', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'When planning a community-based forest management project, what ethical principle should guide a forester''s engagement with the local community?',
   '[{"id":"a","text":"Impose decisions without community input"},{"id":"b","text":"Focus solely on the forester''s expertise"},{"id":"c","text":"Include community consultation and participation"},{"id":"d","text":"Limit community involvement to final stages of the project"}]'::jsonb, 'c'),
  ('fg-g00434', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'What is an ethical way for foresters to address potential conflicts of interest in their work?',
   '[{"id":"a","text":"Hide potential conflicts from clients and colleagues"},{"id":"b","text":"Acknowledge and disclose conflicts to relevant parties"},{"id":"c","text":"Ignore conflicts as they resolve themselves over time"},{"id":"d","text":"Involve only personal interests in decision-making"}]'::jsonb, 'b'),
  ('fg-g00435', 'forest-governance', 'professional-ethics', 'Medium', 'practice',
   'How should professional foresters approach continuing education according to ethical standards?',
